create extension if not exists pgcrypto;
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, image_url text, is_active boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), slug text not null unique, name text not null, description text not null default '', short_description text, price numeric(12,2), old_price numeric(12,2), category_id uuid references public.categories(id) on delete set null, main_image text, images jsonb not null default '[]'::jsonb, alt text, is_active boolean not null default true, is_featured boolean not null default false, sort_order integer not null default 0, seo_title text, seo_description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.reviews (id uuid primary key default gen_random_uuid(), name text not null, review_date date, rating integer check (rating between 1 and 5), body text not null, source text, source_url text, is_published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), status text not null default 'new' check (status in ('new','confirmed','in_progress','ready','delivering','completed','cancelled')), customer_name text, customer_phone text, customer_message text, product_id uuid references public.products(id) on delete set null, product_name text, amount numeric(12,2), payload jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.store_settings (id boolean primary key default true check (id = true), store_name text not null default 'Студия Цветов', address text not null default 'улица Невельского, 3Ак4, Новосибирск', phone_1 text not null default '+7 (952) 916-52-15', phone_2 text not null default '+7 (993) 028-49-94', whatsapp_url text, telegram_url text, max_url text, working_days text not null default 'Ежедневно', working_from time not null default '09:00', working_to time not null default '21:30', timezone text not null default 'Asia/Novosibirsk', latitude double precision not null default 54.993045, longitude double precision not null default 82.833637, route_url text, delivery_method text not null default 'Яндекс Доставка', delivery_price text, delivery_zones text, delivery_hours text, minimum_order text, seo_title text, seo_description text, updated_at timestamptz not null default now());
insert into public.store_settings (id, whatsapp_url, telegram_url, route_url, seo_title, seo_description) values (true, 'https://wa.me/79529165215', 'tg://resolve?phone=79529165215', 'https://yandex.ru/maps/?rtext=~54.993045%2C82.833637&rtt=auto', 'Студия Цветов — цветы с доставкой в Новосибирске', 'Авторские букеты и цветочные композиции с доставкой по Новосибирску.') on conflict (id) do nothing;
create or replace function public.is_admin() returns boolean language sql stable security invoker set search_path = public as $$ select exists (select 1 from public.admin_users where user_id = (select auth.uid())); $$;
alter table public.admin_users enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.reviews enable row level security; alter table public.orders enable row level security; alter table public.store_settings enable row level security;
create policy "public can read active categories" on public.categories for select to anon, authenticated using (is_active = true or public.is_admin());
create policy "public can read active products" on public.products for select to anon, authenticated using (is_active = true or public.is_admin());
create policy "public can read published reviews" on public.reviews for select to anon, authenticated using (is_published = true or public.is_admin());
create policy "public can read store settings" on public.store_settings for select to anon, authenticated using (true);
create policy "admins read admin users" on public.admin_users for select to authenticated using (public.is_admin() or user_id = (select auth.uid()));
create policy "admins insert categories" on public.categories for insert to authenticated with check (public.is_admin());
create policy "admins update categories" on public.categories for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins delete categories" on public.categories for delete to authenticated using (public.is_admin());
create policy "admins insert products" on public.products for insert to authenticated with check (public.is_admin());
create policy "admins update products" on public.products for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins delete products" on public.products for delete to authenticated using (public.is_admin());
create policy "admins insert reviews" on public.reviews for insert to authenticated with check (public.is_admin());
create policy "admins update reviews" on public.reviews for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "admins delete reviews" on public.reviews for delete to authenticated using (public.is_admin());
create policy "admins read orders" on public.orders for select to authenticated using (public.is_admin());
create policy "admins update orders" on public.orders for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy "public can create orders" on public.orders for insert to anon, authenticated with check (true);
create policy "admins update settings" on public.store_settings for update to authenticated using (public.is_admin()) with check (public.is_admin());
create index if not exists products_category_idx on public.products (category_id); create index if not exists reviews_published_idx on public.reviews (is_published, review_date desc); create index if not exists orders_status_created_idx on public.orders (status, created_at desc); create index if not exists orders_product_id_idx on public.orders (product_id);
insert into storage.buckets (id, name, public) values ('product-images', 'product-images', true) on conflict (id) do nothing;
create policy "public can view product images" on storage.objects for select to anon, authenticated using (bucket_id = 'product-images');
create policy "admins upload product images" on storage.objects for insert to authenticated with check (bucket_id = 'product-images' and public.is_admin());
create policy "admins update product images" on storage.objects for update to authenticated using (bucket_id = 'product-images' and public.is_admin()) with check (bucket_id = 'product-images' and public.is_admin());
create policy "admins delete product images" on storage.objects for delete to authenticated using (bucket_id = 'product-images' and public.is_admin());
